local Transport=require('transport');local json=require('dkjson')
local requests={};local pending
local adapter={request=function(_,args,callback)requests[#requests+1]=args;pending=callback;return function()end end}
local transport=Transport.new(adapter,function()return 100 end)
local batch={batchId='batch',json='{"events":[],"progress":null}'};local received,err
transport:send('https://books.example','test-private-token',batch,function(r,e)received=r;err=e end)
assert(requests[1].headers.Authorization=='Bearer test-private-token');assert(requests[1].body==batch.json);assert(requests[1].timeout==15)
pending({status=401,body='untrusted secret content'});assert(err.kind=='auth');assert(not err.message:find('secret',1,true))
for _,status in ipairs({400,409,413,301,302,307,308}) do transport:send('https://books.example','test-private-token',batch,function(r,e)err=e end);pending({status=status,body='bad'});assert(err.kind=='protocol') end
for _,status in ipairs({429,500,502,503}) do transport:send('https://books.example','test-private-token',batch,function(r,e)err=e end);pending({status=status,body='bad'});assert(err.kind=='transient') end
transport:send('https://books.example','test-private-token',batch,function(r,e)err=e end);pending({status=200,body='{}'});assert(err.kind=='protocol')
transport:send('https://books.example','test-private-token',batch,function(r,e)received=r;err=e end);pending({status=200,body=json.encode({protocolVersion=1,batchId='batch',events=setmetatable({},{__jsontype='array'}),progress=json.null,document={id=1}})});assert(received.batchId=='batch');assert(err==nil)
transport:testConnection('http://books.example','test-private-token',function(r,e)err=e end);assert(err.kind=='protocol')
transport:testConnection('https://books.example','test-private-token',function(r,e)err=e end)
pending({error={kind='protocol',code='tls',stage='ca_file',message='private secret'}})
assert(err.message:find('cacert.pem',1,true));assert(not err.message:find('private',1,true));assert(err.code=='tls')
transport:testConnection('https://books.example','test-private-token',function(r,e)err=e end)
pending({error={kind='protocol',code='tls',stage='ssl_module'}})
assert(err.message:find('ssl_module',1,true));assert(not err.message:find('Token',1,true))
transport:testConnection('https://books.example','test-private-token',function(r,e)err=e end)
pending({error={kind='transient',code='timeout',stage='handshake'}})
assert(err.kind=='transient' and err.code=='timeout')
assert(not err.message:find('certificados',1,true),'timeout feedback does not prescribe certificate repair')
transport:send('https://books.example','test-private-token',batch,function(r,e)err=e end)
pending({error={kind='transient',code='cancelled',stage='ui_dismissed'}})
assert(err.message:find('interrompido',1,true) and not err.message:find('conectar',1,true),'dismissal must not be presented as a connection failure')
assert(err.stage=='ui_dismissed')
transport:send('https://books.example','test-private-token',batch,function(r,e)err=e end)
pending({error={kind='transient',code='network',stage='handshake',reason='closed'}})
assert(err.kind=='transient' and err.code=='network' and err.reason=='closed')
assert(err.message=='Não foi possível conectar ao servidor pessoal' and not err.message:find('certificados',1,true),'closed handshake is not a certificate message')
transport:send('https://books.example','test-private-token',batch,function(r,e)err=e end)
pending({error={kind='protocol',code='tls',stage='handshake',reason='unknown'}})
assert(err.code=='tls' and err.reason=='unknown' and err.message:find('certificados',1,true))
transport:send('https://books.example','test-private-token',batch,function(r,e)err=e end)
pending({error={kind='transient',code='network',stage='handshake',reason='closed'}})
assert(err.stage=='handshake' and err.message=='Não foi possível conectar ao servidor pessoal','closed handshake keeps its stage but not the certificate message')
transport:send('https://books.example','test-private-token',batch,function(r,e)err=e end)
pending({error={kind='transient',code='network',stage='tcp_connect'}})
assert(err.stage=='tcp_connect' and err.message:find('(tcp_connect)',1,true),'tcp_connect keeps its stage message')
transport:send('https://books.example','test-private-token',batch,function(r,e)err=e end)
pending({error={kind='transient',code='network',stage='http_io'}})
assert(err.stage=='http_io' and err.message:find('(http_io)',1,true))
assert(Transport.validServerId('s1') and Transport.validServerId(string.rep('x',64)))
assert(not Transport.validServerId('') and not Transport.validServerId(string.rep('x',65)) and not Transport.validServerId(nil) and not Transport.validServerId(1))
local info;transport:serverInfo('https://books.example','test-private-token',function(r,e)info=r;err=e end)
assert(requests[#requests].url=='https://books.example/v1/server' and requests[#requests].method=='GET' and requests[#requests].headers.Authorization=='Bearer test-private-token')
pending({status=200,body=json.encode({protocolVersion=1,serverId='s1'})});assert(info.serverId=='s1' and err==nil)
for _,bad in ipairs({'',string.rep('x',65)}) do
 info=nil;transport:serverInfo('https://books.example','test-private-token',function(r,e)info=r;err=e end)
 pending({status=200,body=json.encode({protocolVersion=1,serverId=bad})});assert(info==nil and err.kind=='protocol' and err.code=='response')
end
info=nil;transport:serverInfo('https://books.example','test-private-token',function(r,e)info=r;err=e end)
pending({status=200,body=json.encode({protocolVersion=1})});assert(info==nil and err.code=='response','missing serverId is incompatible for serverInfo')
transport:serverInfo('https://books.example','test-private-token',function(r,e)info=r;err=e end);pending({status=401,body='x'});assert(err.kind=='auth')
transport:testConnection('https://books.example','test-private-token',function(r,e)info=r;err=e end)
pending({status=200,body=json.encode({protocolVersion=1,timeZone='UTC',counts={},serverId='s1'})});assert(info.serverId=='s1')
transport:send('https://books.example','test-private-token',batch,function(r,e)info=r;err=e end)
pending({status=200,body=json.encode({protocolVersion=1,batchId='batch',events=setmetatable({},{__jsontype='array'}),progress=json.null,document={id=1},serverId='s1'})});assert(info.serverId=='s1')
